query TroubleshootingInsights($details: IssueDetails!) {
  troubleshootingInsights(details: $details) {
    causes {
      id
      name
      subContextValue
      confidence
      confidenceLevel
      breakdown {
        index {
          name
          values
        }
        intCols {
          name
          values
        }
        floatCols {
          name
          values
        }
      }
    }
  }
}
